def register(schemas, frame_spec):
    """Register the requested value.
    
    Args:
        schemas (Any): Input for the register operation.
        frame_spec (Any): Input for the register operation."""
    schemas.update({name: frame_spec(**fields) for name, fields in DEFINITIONS.items()})

DEFINITIONS["futures"] = dict(strings=("instrument_id", "symbol", "name", "currency", "quote_unit", "quantity_unit"), numbers=("last_price", "closing_price", "volume", "turnover"), integers=("trade_count",), key=("instrument_id",), display=("instrument_id", "symbol", "last_price", "closing_price", "volume"))

# Preserve each source row position and scope its identity to its instrument/date.
for _name in ('trades','order_book','instrument_states','thresholds','shareholders','share_capital','fund_nav','dividends','disclosures','messages'):
    _entry = DEFINITIONS[_name]
    _entry['integers'] = tuple(dict.fromkeys((*_entry.get('integers', ()), 'source_position')))
    _entry['key'] = (('registration_no', 'date', 'source_position') if _name == 'fund_nav' else ('ins_code', 'date', 'source_position'))

